export class TInletNode {
  numInletLinks: number = 0;
  numStdInletLinks: number = 0;
  numCustomInlets: number = 0;
  totalInletArea: number = 0.0;
  clone(): TInletNode {
    const c = new TInletNode();
    c.numInletLinks = this.numInletLinks;
    c.numStdInletLinks = this.numStdInletLinks;
    c.numCustomInlets = this.numCustomInlets;
    c.totalInletArea = this.totalInletArea;
    return c;
  }
}

export class MathExpr {
  opcode: number = 0;
  ivar: number = 0;
  fvalue: number = 0.0;
  prev: MathExpr = null;
  next: MathExpr = null;
  clone(): MathExpr {
    const c = new MathExpr();
    c.opcode = this.opcode;
    c.ivar = this.ivar;
    c.fvalue = this.fvalue;
    c.prev = this.prev;
    c.next = this.next;
    return c;
  }
}

