export class TFile {
  name: CPtr = R.buf(260);
  mode: number = 0;
  state: number = 0;
  file: CFile = null;
  clone(): TFile {
    const c = new TFile();
    c.name = R.copyBuf(this.name);
    c.mode = this.mode;
    c.state = this.state;
    c.file = this.file;
    return c;
  }
}

export class TTableEntry {
  x: number = 0.0;
  y: number = 0.0;
  next: TTableEntry = null;
  clone(): TTableEntry {
    const c = new TTableEntry();
    c.x = this.x;
    c.y = this.y;
    c.next = this.next;
    return c;
  }
}

export class TTable {
  ID: CPtr = null;
  curveType: number = 0;
  refersTo: number = 0;
  dxMin: number = 0.0;
  lastDate: number = 0.0;
  x1: number = 0.0;
  x2: number = 0.0;
  y1: number = 0.0;
  y2: number = 0.0;
  firstEntry: TTableEntry = null;
  lastEntry: TTableEntry = null;
  thisEntry: TTableEntry = null;
  file: TFile = new TFile();
  clone(): TTable {
    const c = new TTable();
    c.ID = this.ID;
    c.curveType = this.curveType;
    c.refersTo = this.refersTo;
    c.dxMin = this.dxMin;
    c.lastDate = this.lastDate;
    c.x1 = this.x1;
    c.x2 = this.x2;
    c.y1 = this.y1;
    c.y2 = this.y2;
    c.firstEntry = this.firstEntry;
    c.lastEntry = this.lastEntry;
    c.thisEntry = this.thisEntry;
    c.file = this.file.clone();
    return c;
  }
}

export class TGage {
  ID: CPtr = null;
  dataSource: number = 0;
  tSeries: number = 0;
  fname: CPtr = R.buf(260);
  staID: CPtr = R.buf(1025);
  startFileDate: number = 0.0;
  endFileDate: number = 0.0;
  rainType: number = 0;
  rainInterval: number = 0;
  rainUnits: number = 0;
  snowFactor: number = 0.0;
  startFilePos: number = 0;
  endFilePos: number = 0;
  currentFilePos: number = 0;
  rainAccum: number = 0.0;
  unitsFactor: number = 0.0;
  startDate: number = 0.0;
  endDate: number = 0.0;
  nextDate: number = 0.0;
  rainfall: number = 0.0;
  nextRainfall: number = 0.0;
  apiRainfall: number = 0.0;
  reportRainfall: number = 0.0;
  pastRain: Float64Array = new Float64Array(49);
  pastInterval: number = 0;
  coGage: number = 0;
  isUsed: number = 0;
  isCurrent: number = 0;
  clone(): TGage {
    const c = new TGage();
    c.ID = this.ID;
    c.dataSource = this.dataSource;
    c.tSeries = this.tSeries;
    c.fname = R.copyBuf(this.fname);
    c.staID = R.copyBuf(this.staID);
    c.startFileDate = this.startFileDate;
    c.endFileDate = this.endFileDate;
    c.rainType = this.rainType;
    c.rainInterval = this.rainInterval;
    c.rainUnits = this.rainUnits;
    c.snowFactor = this.snowFactor;
    c.startFilePos = this.startFilePos;
    c.endFilePos = this.endFilePos;
    c.currentFilePos = this.currentFilePos;
    c.rainAccum = this.rainAccum;
    c.unitsFactor = this.unitsFactor;
    c.startDate = this.startDate;
    c.endDate = this.endDate;
    c.nextDate = this.nextDate;
    c.rainfall = this.rainfall;
    c.nextRainfall = this.nextRainfall;
    c.apiRainfall = this.apiRainfall;
    c.reportRainfall = this.reportRainfall;
    c.pastRain = this.pastRain.slice();
    c.pastInterval = this.pastInterval;
    c.coGage = this.coGage;
    c.isUsed = this.isUsed;
    c.isCurrent = this.isCurrent;
    return c;
  }
}

