// climate.c:153
export function climate_readParams(tok: any, ntoks: number): number {
  let i: number = 0, j: number = 0, k: number = 0, x: Float64Array = null, y: R.Box = null, aDate: R.Box = null, fname: CPtr = null;
  i = 0;
  j = 0;
  k = 0;
  x = new Float64Array(6);
  y = new R.Box(0.0);
  aDate = new R.Box(0.0);
  fname = R.buf(260);
  k = findmatch(tok[0], TempKeyWords);
  if ((k < 0))
  {
    return error_setInpError(ERR_KEYWORD, tok[0]);
  }
  switch (k) {
    case 0:
      if ((ntoks < 2))
      {
        return error_setInpError(ERR_ITEMS, L0);
      }
      i = project_findObject(TSERIES, tok[1]);
      if ((i < 0))
      {
        return error_setInpError(ERR_NAME, tok[1]);
      }
      Temp.dataSource = TSERIES_TEMP;
      Temp.tSeries = i;
      Tseries[i].refersTo = TSERIES_TEMP;
      break;
    case 1:
      if ((ntoks < 2))
      {
        return error_setInpError(ERR_ITEMS, L0);
      }
      Temp.dataSource = FILE_TEMP;
      Fclimate.mode = USE_FILE;
      sstrncpy(fname, tok[1], R.toUL(259));
      sstrncpy(Fclimate.name, addAbsolutePath(fname), R.toUL(259));
      Temp.fileStartDate = (0 - 693594);
      if ((ntoks > 2))
      {
        if ((tok[2].g(0) !== 42))
        {
          if (!(datetime_strToDate(tok[2], aDate) !== 0))
          {
            return error_setInpError(ERR_DATETIME, tok[2]);
          }
          Temp.fileStartDate = aDate.v;
        }
      }
      FileTempUnits = DEG_F;
      if ((UnitSystem === SI))
      {
        FileTempUnits = DEG_C;
      }
      if ((ntoks > 3))
      {
        i = findmatch(tok[3], TempUnitsWords);
        if ((i < 0))
        {
          return error_setInpError(ERR_KEYWORD, tok[3]);
        }
        FileTempUnits = i;
      }
      break;
    case 2:
      if ((strcomp(tok[1], L1) !== 0))
      {
        Wind.type = FILE_WIND;
      }
      else
      {
        if ((ntoks < 14))
        {
          return error_setInpError(ERR_ITEMS, L0);
        }
        Wind.type = MONTHLY_WIND;
        for (i = 0; (i < 12); i++)
        {
          if (!(getDouble(tok[(i + 2)], y) !== 0))
          {
            return error_setInpError(ERR_NUMBER, tok[(i + 2)]);
          }
          Wind.aws[i] = y.v;
        }
      }
      break;
    case 3:
      if ((ntoks < 7))
      {
        return error_setInpError(ERR_ITEMS, L0);
      }
      for (i = 1; (i < 7); i++)
      {
        if (!(getDouble(tok[i], new R.ElemRef(x, (i - 1))) !== 0))
        {
          return error_setInpError(ERR_NUMBER, tok[i]);
        }
      }
      if ((UnitSystem === SI))
      {
        x[0] = (((9.0 / 5.0) * x[0]) + 32.0);
      }
      Snow.snotmp = x[0];
      Snow.tipm = x[1];
      Snow.rnm = x[2];
      Temp.elev = (x[3] / UCF(LENGTH));
      Temp.anglat = x[4];
      Temp.dtlong = (x[5] / 60.0);
      break;
    case 4:
      if ((ntoks < 12))
      {
        return error_setInpError(ERR_ITEMS, L0);
      }
      if ((match(tok[1], L2) !== 0))
      {
        i = 0;
      }
      else if ((match(tok[1], L3) !== 0))
      {
        i = 1;
      }
      else
      {
        return error_setInpError(ERR_KEYWORD, tok[1]);
      }
      for (j = 0; (j < 10); j++)
      {
        if ((((!(getDouble(tok[(j + 2)], y) !== 0)) || (y.v < 0.0)) || (y.v > 1.0)))
        {
          return error_setInpError(ERR_NUMBER, tok[(j + 2)]);
        }
        Snow.adc[i][j] = y.v;
      }
      break;
  }
  return 0;
}

// climate.c:285
export function climate_readEvapParams(tok: any, ntoks: number): number {
  let i: number = 0, k: number = 0, x: R.Box = null;
  i = 0;
  k = 0;
  x = new R.Box(0.0);
  k = findmatch(tok[0], EvapTypeWords);
  if ((k < 0))
  {
    return error_setInpError(ERR_KEYWORD, tok[0]);
  }
  if ((k === RECOVERY))
  {
    if ((ntoks < 2))
    {
      return error_setInpError(ERR_ITEMS, L0);
    }
    i = project_findObject(TIMEPATTERN, tok[1]);
    if ((i < 0))
    {
      return error_setInpError(ERR_NAME, tok[1]);
    }
    Evap.recoveryPattern = i;
    return 0;
  }
  if ((k === DRYONLY))
  {
    if ((ntoks < 2))
    {
      return error_setInpError(ERR_ITEMS, L0);
    }
    if ((strcomp(tok[1], L4) !== 0))
    {
      Evap.dryOnly = 0;
    }
    else if ((strcomp(tok[1], L5) !== 0))
    {
      Evap.dryOnly = 1;
    }
    else
    {
      return error_setInpError(ERR_KEYWORD, tok[1]);
    }
    return 0;
  }
  Evap.type = k;
  if (((k !== TEMPERATURE_EVAP) && (ntoks < 2)))
  {
    return error_setInpError(ERR_ITEMS, L0);
  }
  switch (k) {
    case CONSTANT_EVAP:
      if (!(getDouble(tok[1], x) !== 0))
      {
        return error_setInpError(ERR_NUMBER, tok[1]);
      }
      for (i = 0; (i < 12); i++)
      {
        Evap.monthlyEvap[i] = x.v;
      }
      break;
    case MONTHLY_EVAP:
      if ((ntoks < 13))
      {
        return error_setInpError(ERR_ITEMS, L0);
      }
      for (i = 0; (i < 12); i++)
      {
        if (!(getDouble(tok[(i + 1)], new R.ElemRef(Evap.monthlyEvap, i)) !== 0))
        {
          return error_setInpError(ERR_NUMBER, tok[(i + 1)]);
        }
      }
      break;
    case TIMESERIES_EVAP:
      i = project_findObject(TSERIES, tok[1]);
      if ((i < 0))
      {
        return error_setInpError(ERR_NAME, tok[1]);
      }
      Evap.tSeries = i;
      Tseries[i].refersTo = TIMESERIES_EVAP;
      break;
    case FILE_EVAP:
      if ((ntoks > 1))
      {
        if ((ntoks < 13))
        {
          return error_setInpError(ERR_ITEMS, L0);
        }
        for (i = 0; (i < 12); i++)
        {
          if (!(getDouble(tok[(i + 1)], new R.ElemRef(Evap.panCoeff, i)) !== 0))
          {
            return error_setInpError(ERR_NUMBER, tok[(i + 1)]);
          }
        }
      }
      break;
  }
  return 0;
}

