// inflow.c:456
export function getPatternFactor(p: number, month: number, day: number, hour: number): number {
  switch (Pattern[p].type) {
    case MONTHLY_PATTERN:
      if (((month >= 0) && (month < 12)))
      {
        return Pattern[p].factor[month];
      }
      break;
    case DAILY_PATTERN:
      if (((day >= 0) && (day < 7)))
      {
        return Pattern[p].factor[day];
      }
      break;
    case HOURLY_PATTERN:
      if (((hour >= 0) && (hour < 24)))
      {
        return Pattern[p].factor[hour];
      }
      break;
    case WEEKEND_PATTERN:
      if (((day === 0) || (day === 6)))
      {
        if (((hour >= 0) && (hour < 24)))
        {
          return Pattern[p].factor[hour];
        }
      }
      break;
  }
  return 1.0;
}

