// project.c:287
export function project_init(): number {
  let j: number = 0, k: number = 0;
  j = 0;
  k = 0;
  climate_initState();
  lid_initState();
  for (j = 0; (j < Nobjects[TSERIES]); j++)
  {
    table_tseriesInit(Tseries[j]);
  }
  for (j = 0; (j < Nobjects[GAGE]); j++)
  {
    gage_initState(j);
  }
  k = 1;
  for (j = 0; (j < Nobjects[SUBCATCH]); j++)
  {
    subcatch_initState(j);
    if ((Subcatch[j].rptFlag > 0))
    {
      Subcatch[j].rptFlag = k;
      k++;
    }
  }
  k = 1;
  for (j = 0; (j < Nobjects[NODE]); j++)
  {
    node_initState(j);
    if ((Node[j].rptFlag > 0))
    {
      Node[j].rptFlag = k;
      k++;
    }
  }
  k = 1;
  for (j = 0; (j < Nobjects[LINK]); j++)
  {
    link_initState(j);
    if ((Link[j].rptFlag > 0))
    {
      Link[j].rptFlag = k;
      k++;
    }
  }
  return ErrorCode;
}

