export function project_addObject(type_: number, id: CPtr, n: number): number {
  let result: number = 0, len: number = 0, newID: CPtr = null;
  result = 0;
  len = 0;
  newID = null;
  if ((project_findObject(type_, id) >= 0))
  {
    return 0;
  }
  len = R.strlen(id);
  newID = Alloc((R.toUL(((len + 1))) * 1 + 0));
  sstrncpy(newID, id, R.toUL(len));
  result = HTinsert(Htable[type_], newID, n);
  if ((result === 0))
  {
    result = (0 - 1);
  }
  return result;
}

