// qualrout.c:100
export function qualrout_execute(tStep: number): void {
  let i: number = 0, j: number = 0, qIn: number = 0, vAvg: number = 0;
  i = 0;
  j = 0;
  qIn = 0.0;
  vAvg = 0.0;
  for (i = 0; (i < Nobjects[LINK]); i++)
  {
    findLinkMassFlow(i, tStep);
  }
  for (j = 0; (j < Nobjects[NODE]); j++)
  {
    Node[j].qualInflow = Node[j].inflow;
    qIn = Node[j].qualInflow;
    vAvg = (((Node[j].oldVolume + Node[j].newVolume)) / 2.0);
    if ((Node[j].treatment !== null))
    {
      if ((qIn < 1e-10))
      {
        qIn = 0.0;
      }
      treatmnt_setInflow(qIn, Node[j].newQual);
    }
    if (((Node[j].type === STORAGE) || (Node[j].oldVolume > ZeroVolume)))
    {
      findStorageQual(j, tStep);
    }
    else
    {
      findNodeQual(j);
    }
    if ((Node[j].treatment !== null))
    {
      treatmnt_treat(j, qIn, vAvg, tStep);
    }
  }
  for (i = 0; (i < Nobjects[LINK]); i++)
  {
    findLinkQual(i, tStep);
  }
}

// qualrout.c:146
export function getMixedQual(c: number, v1: number, wIn: number, qIn: number, tStep: number): number {
  let vIn: number = 0, cIn: number = 0, cMax: number = 0;
  vIn = 0.0;
  cIn = 0.0;
  cMax = 0.0;
  if ((qIn <= 1e-10))
  {
    return c;
  }
  vIn = (qIn * tStep);
  cIn = ((wIn * tStep) / vIn);
  cMax = (((((c) >= (cIn))) ? (c) : (cIn)));
  c = ((((c * v1) + (wIn * tStep))) / ((v1 + vIn)));
  c = (((((c) <= (cMax))) ? (c) : (cMax)));
  c = (((((c) >= (0.0))) ? (c) : (0.0)));
  return c;
}

// qualrout.c:179
export function findLinkMassFlow(i: number, tStep: number): void {
  let j: number = 0, p: number = 0, qLink: number = 0, w: number = 0;
  j = 0;
  p = 0;
  qLink = 0.0;
  w = 0.0;
  qLink = Link[i].newFlow;
  j = Link[i].node2;
  if ((qLink < 0.0))
  {
    j = Link[i].node1;
  }
  qLink = Math.abs(qLink);
  if ((RouteModel !== DW))
  {
    qLink -= (inlet_capturedFlow(i));
  }
  for (p = 0; (p < Nobjects[POLLUT]); p++)
  {
    w = (qLink * Link[i].oldQual[p]);
    Node[j].newQual[p] += w;
    Link[i].totalLoad[p] += (w * tStep);
  }
  Node[j].qualInflow += qLink;
}

// qualrout.c:221
export function findNodeQual(j: number): void {
  let p: number = 0, qNode: number = 0;
  p = 0;
  qNode = 0.0;
  qNode = Node[j].qualInflow;
  if ((qNode > 1e-10))
  {
    for (p = 0; (p < Nobjects[POLLUT]); p++)
    {
      Node[j].newQual[p] /= qNode;
    }
  }
  else
  {
    for (p = 0; (p < Nobjects[POLLUT]); p++)
    {
      if ((Node[j].newDepth > ZeroDepth))
      {
        Node[j].newQual[p] = Node[j].oldQual[p];
      }
      else
      {
        Node[j].newQual[p] = 0.0;
      }
    }
  }
}

// qualrout.c:253
export function findLinkQual(i: number, tStep: number): void {
  let j: number = 0, k: number = 0, p: number = 0, wIn: number = 0, qIn: number = 0, qSeep: number = 0, v1: number = 0, v2: number = 0, c1: number = 0, c2: number = 0, vEvap: number = 0, vLosses: number = 0, fEvap: number = 0, barrels: number = 0;
  j = 0;
  k = 0;
  p = 0;
  wIn = 0.0;
  qIn = 0.0;
  qSeep = 0.0;
  v1 = 0.0;
  v2 = 0.0;
  c1 = 0.0;
  c2 = 0.0;
  vEvap = 0.0;
  vLosses = 0.0;
  fEvap = 0.0;
  barrels = 0.0;
  j = Link[i].node1;
  if ((Link[i].newFlow < 0.0))
  {
    j = Link[i].node2;
  }
  if (((Link[i].type !== CONDUIT) || (Link[i].xsect.type === DUMMY)))
  {
    for (p = 0; (p < Nobjects[POLLUT]); p++)
    {
      Link[i].newQual[p] = Node[j].newQual[p];
    }
    return;
  }
  k = Link[i].subIndex;
  barrels = Conduit[k].barrels;
  qIn = (Math.abs(Conduit[k].q1) * barrels);
  qSeep = (Conduit[k].seepLossRate * barrels);
  vEvap = ((Conduit[k].evapLossRate * barrels) * tStep);
  v1 = Link[i].oldVolume;
  v2 = Link[i].newVolume;
  vLosses = ((qSeep * tStep) + vEvap);
  fEvap = 1.0;
  if (((vEvap > 0.0) && (v1 > ZeroVolume)))
  {
    fEvap += (vEvap / v1);
  }
  if ((RouteModel === SF))
  {
    findSFLinkQual(i, qSeep, fEvap, tStep);
    return;
  }
  if ((RouteModel === DW))
  {
    qIn = (qIn + ((((v2 + vLosses) - v1)) / tStep));
    qIn = (((((qIn) >= (0.0))) ? (qIn) : (0.0)));
  }
  for (p = 0; (p < Nobjects[POLLUT]); p++)
  {
    c1 = Link[i].oldQual[p];
    massbal_addSeepageLoss(p, (qSeep * c1));
    c1 *= fEvap;
    c2 = getReactedQual(p, c1, v1, tStep);
    wIn = (Node[j].newQual[p] * qIn);
    c2 = getMixedQual(c2, v1, wIn, qIn, tStep);
    if (((v2 < ZeroVolume) || (Link[i].newDepth <= ZeroDepth)))
    {
      massbal_addToFinalStorage(p, (c2 * v2));
      c2 = 0.0;
    }
    Link[i].newQual[p] = c2;
  }
}

// qualrout.c:357
export function findSFLinkQual(i: number, qSeep: number, fEvap: number, tStep: number): void {
  let j: number = 0, p: number = 0, c1: number = 0, c2: number = 0, lossRate: number = 0;
  j = Link[i].node1;
  p = 0;
  c1 = 0.0;
  c2 = 0.0;
  lossRate = 0.0;
  for (p = 0; (p < Nobjects[POLLUT]); p++)
  {
    c1 = Node[j].newQual[p];
    massbal_addSeepageLoss(p, (qSeep * c1));
    c1 *= fEvap;
    c2 = c1;
    if ((Pollut[p].kDecay > 0.0))
    {
      c2 = (c1 * M.exp((-Pollut[p].kDecay * tStep)));
      c2 = (((((0.0) >= (c2))) ? (0.0) : (c2)));
      lossRate = (((c1 - c2)) * Link[i].newFlow);
      massbal_addReactedMass(p, lossRate);
    }
    Link[i].newQual[p] = c2;
  }
}

