// roadway.c:85
export function roadway_getInflow(j: number, dir: number, hRoad: number, h1: number, h2: number): number {
  let k: number = 0, roadSurf: number = 0, useVariableCd: number = 0, length: number = 0, roadWidth: number = 0, hWr: number = 0, ht: number = 0, cD: number = 0, q: number = 0, dqdh: number = 0;
  k = 0;
  roadSurf = 0;
  useVariableCd = 0;
  length = 0.0;
  roadWidth = 0.0;
  hWr = 0.0;
  ht = 0.0;
  cD = 0.0;
  q = 0.0;
  dqdh = 0.0;
  if ((Link[j].type !== WEIR))
  {
    return 0.0;
  }
  k = Link[j].subIndex;
  roadWidth = Weir[k].roadWidth;
  roadSurf = Weir[k].roadSurface;
  cD = Weir[k].cDisch1;
  if ((UnitSystem === SI))
  {
    cD = (cD / 0.552);
  }
  useVariableCd = 0;
  if (((roadWidth > 0.0) && (roadSurf >= 1)))
  {
    useVariableCd = 1;
  }
  hWr = (h1 - hRoad);
  ht = (h2 - hRoad);
  if ((hWr > 0.0001))
  {
    if ((useVariableCd !== 0))
    {
      cD = getCd(hWr, ht, roadWidth, roadSurf);
    }
    length = Link[j].xsect.wMax;
    q = ((cD * length) * M.pow(hWr, 1.5));
    dqdh = ((1.5 * q) / hWr);
  }
  Link[j].dqdh = dqdh;
  Link[j].newDepth = ((((((h1 - hRoad)) >= (0.0))) ? ((h1 - hRoad)) : (0.0)));
  Link[j].flowClass = SUBCRITICAL;
  if ((hRoad > h2))
  {
    if ((dir === 1.0))
    {
      Link[j].flowClass = DN_CRITICAL;
    }
    else
    {
      Link[j].flowClass = UP_CRITICAL;
    }
  }
  return (dir * q);
}

// roadway.c:146
export function getCd(hWr: number, ht: number, roadWidth: number, roadSurf: number): number {
  let kT: number = 0, hL: number = 0, htH: number = 0, cR: number = 0;
  kT = 1.0;
  hL = 0.0;
  htH = 0.0;
  cR = 0.0;
  if ((hWr <= 0.0))
  {
    return 0.0;
  }
  hL = (hWr / roadWidth);
  if ((hL <= 0.15))
  {
    if ((roadSurf === PAVED))
    {
      cR = getY(hWr, Cr_Low_Paved, N_Cr_Low_Paved);
    }
    else
    {
      cR = getY(hWr, Cr_Low_Gravel, N_Cr_Low_Gravel);
    }
  }
  else
  {
    if ((roadSurf === PAVED))
    {
      cR = getY(hL, Cr_High_Paved, N_Cr_High_Paved);
    }
    else
    {
      cR = getY(hL, Cr_High_Gravel, N_Cr_High_Gravel);
    }
  }
  if ((ht > 0.0))
  {
    htH = (ht / hWr);
    if ((roadSurf === PAVED))
    {
      kT = getY(htH, Kt_Paved, N_Kt_Paved);
    }
    else
    {
      kT = getY(htH, Kt_Gravel, N_Kt_Gravel);
    }
  }
  return (cR * kT);
}

// roadway.c:176
export function getY(x: number, table: any, n: number): number {
  let i: number = 0, x1: number = 0, y1: number = 0, dx: number = 0, dy: number = 0;
  i = 0;
  x1 = 0.0;
  y1 = 0.0;
  dx = 0.0;
  dy = 0.0;
  if ((x <= table[0][0]))
  {
    return table[0][1];
  }
  if ((x >= (table[(n - 1)])[0]))
  {
    return (table[(n - 1)])[1];
  }
  for (i = 1; (i < n); i++)
  {
    if ((x <= table[i][0]))
    {
      x1 = (table[(i - 1)])[0];
      dx = (table[i][0] - x1);
      y1 = (table[(i - 1)])[1];
      dy = (table[i][1] - y1);
      return (y1 + ((((x - x1)) * dy) / dx));
    }
  }
  return (table[(n - 1)])[1];
}

