// routing.c:337
export function isBetweenEvents(currentDate: number): number {
  if ((NumEvents === 0))
  {
    return 0;
  }
  if ((currentDate > Event[NextEvent].end))
  {
    NextEvent++;
    return 1;
  }
  else if ((currentDate >= Event[NextEvent].start))
  {
    return 0;
  }
  return 1;
}

